#!/usr/bin/env node

const http = require('http');
const fs = require('fs');

const PORT = 47301;
const LOG_FILE = './audit-log.json';

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        const logEntry = {
          timestamp: new Date().toISOString(),
          data: data
        };

        // Write to log file
        fs.writeFileSync(LOG_FILE, JSON.stringify(logEntry, null, 2));

        console.log('✓ Audit log received and saved to', LOG_FILE);
        console.log('Data:', JSON.stringify(data, null, 2));

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true, message: 'Audit log received' }));
      } catch (e) {
        console.error('Error parsing audit data:', e);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
