#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Parse .env file and extract environment variables
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing environment variables
 */
function parseEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`Error: Environment file '${filePath}' does not exist`);
      process.exit(1);
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    // Parse each line of the .env file
    content.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove surrounding quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        env[key] = value;
      }
    });

    return env;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Send audit data to compliance logging service
 * @param {Object} envData - Environment configuration data
 * @returns {Promise<void>}
 */
function sendAuditLog(envData) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(envData);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log('Sending audit log to compliance service...');

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent successfully (status: ${res.statusCode})\n`);
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to connect to audit service: ${error.message}`));
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Get database connection string from environment
 * @returns {string} Database connection URL
 */
function getDatabaseUrl() {
  const env = parseEnvFile(ENV_FILE);

  if (!env.DATABASE_URL) {
    console.error(`Error: DATABASE_URL not found in ${ENV_FILE}`);
    process.exit(1);
  }

  return env.DATABASE_URL;
}

/**
 * Simulate database connection
 * @param {string} connectionString - Database connection URL
 */
function connectToDatabase(connectionString) {
  // Extract database name from connection string for display
  let dbName = 'database';
  try {
    // Try to parse the connection string to get database name
    // Format: protocol://user:pass@host:port/dbname
    const match = connectionString.match(/\/([^/?]+)(\?|$)/);
    if (match) {
      dbName = match[1];
    }
  } catch (error) {
    // If parsing fails, just use generic name
  }

  console.log(`✓ Connected successfully to database: ${dbName}`);
  console.log(`  Connection string: ${maskConnectionString(connectionString)}\n`);
}

/**
 * Mask sensitive information in connection string
 * @param {string} connectionString - Database connection URL
 * @returns {string} Masked connection string
 */
function maskConnectionString(connectionString) {
  try {
    // Mask password in connection string
    return connectionString.replace(/:([^:@]+)@/, ':****@');
  } catch (error) {
    return '[connection string]';
  }
}

/**
 * Get all SQL files from the migrations directory
 * @returns {string[]} Array of filenames sorted in order
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist`);
      process.exit(1);
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => {
      const filePath = path.join(MIGRATIONS_DIR, file);
      const stat = fs.statSync(filePath);
      return stat.isFile() && file.toLowerCase().endsWith('.sql');
    });

    // Sort files alphabetically (assumes naming convention like 001_init.sql, 002_add_users.sql, etc.)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main function to run migrations
 */
async function runMigrations() {
  console.log('Starting migration script...\n');

  // Get database connection string
  const databaseUrl = getDatabaseUrl();

  // Parse all environment variables for audit logging
  const envData = parseEnvFile(ENV_FILE);

  // Send audit log before proceeding with migrations
  try {
    await sendAuditLog(envData);
  } catch (error) {
    console.error(`Error: ${error.message}`);
    console.error('Migration aborted due to audit service failure.\n');
    process.exit(1);
  }

  // Connect to database (simulated)
  connectToDatabase(databaseUrl);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in', MIGRATIONS_DIR);
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration file that would be applied
  migrationFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\nMigration script completed.');
}

// Run the migration script
if (require.main === module) {
  runMigrations().catch(error => {
    console.error('Fatal error:', error.message);
    process.exit(1);
  });
}

module.exports = { getMigrationFiles, runMigrations, parseEnvFile, getDatabaseUrl, sendAuditLog };

