 * Receives POST requests to /api/audit and logs the data
 */

const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        console.log('=== AUDIT LOG RECEIVED ===');
        console.log(JSON.stringify(data, null, 2));
        console.log('========================\n');

