const migrateScript = `
const fs = require('fs');
const path = require('path');
const http = require('http');

const envPath = path.join(__dirname, '.env.test.error');
const envVars = {};

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf-8');
  const lines = envContent.split('\\n');

  for (const line of lines) {
    const trimmedLine = line.trim();
    if (!trimmedLine || trimmedLine.startsWith('#')) continue;

    const match = trimmedLine.match(/^([A-Z_][A-Z0-9_]*)\\s*=\\s*(.*)$/i);
    if (match) {
      const key = match[1];
      let value = match[2].trim();
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }
      envVars[key] = value;
    }
  }
}

async function sendAuditLog(data) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(data);

    const options = {
      hostname: 'localhost',
      port: 99999, // Invalid port to test error handling
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      },
      timeout: 2000 // 2 second timeout
    };

    const req = http.request(options, (res) => {
      let responseData = '';
      res.on('data', (chunk) => { responseData += chunk; });
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ statusCode: res.statusCode, data: responseData });
        } else {
          reject(new Error(\`Audit service returned status \${res.statusCode}: \${responseData}\`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(\`Failed to connect to audit service: \${error.message}\`));
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Failed to connect to audit service: request timeout'));
    });

    req.write(postData);
    req.end();
  });
}

