let failed = 0;

function runTest(name, fn) {
  process.stdout.write(`Testing: ${name}... `);
  try {
    fn();
    console.log('✓ PASS');
    passed++;
  } catch (error) {
    console.log('✗ FAIL');
    console.log(`  Error: ${error.message}`);
    failed++;
  }
}

