const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Load environment variables from .env.test file
 * @returns {Object} Environment variables as key-value pairs
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Error: Environment file '${ENV_FILE}' does not exist`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const envVars = {};

    // Parse the .env file
    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error('Error reading environment file:', error.message);
    return {};
  }
}

/**
 * Send audit data to the compliance logging service
 * @param {Object} envVars - Environment variables to audit
 * @returns {Promise<void>}
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log(`Sending audit log to ${AUDIT_SERVICE_URL}...`);

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`Audit log sent successfully (Status: ${res.statusCode})\n`);
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Get all SQL files from the migrations directory, sorted by filename
 * @returns {string[]} Array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort them
    const sqlFiles = files
      .filter(file => file.toLowerCase().endsWith('.sql'))
      .sort(); // Sort alphabetically (which works well for numbered migrations)

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

/**
 * Main function to run migrations
 */
async function runMigrations() {
  console.log('=== Database Migration Script ===\n');

  // Load environment variables
  const envVars = loadEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Send audit log before running migrations
  try {
    await sendAuditLog(envVars);
  } catch (error) {
    console.error('Error:', error.message);
    console.error('Failed to send audit log. Aborting migration.');
    process.exit(1);
  }

  // Log successful connection (simulated)
  console.log(`Connected to database successfully`);
  console.log(`Database URL: ${databaseUrl}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\n=== Migration complete ===');
}

// Run the migration script
runMigrations();

