#!/usr/bin/env node

const http = require('http');

/**
 * Mock Audit Service for Testing
 * Listens on http://localhost:47301/api/audit
 */

const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.url === '/api/audit' && req.method === 'POST') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      console.log('=== Audit Service Received Data ===\n');
      console.log('Headers:', JSON.stringify(req.headers, null, 2));
      console.log('\nRaw Body:', body);

      try {
        const data = JSON.parse(body);
        console.log('\n✓ Successfully parsed JSON data:');
        console.log(JSON.stringify(data, null, 2));

        console.log('\n📊 Audit Data Summary:');
        console.log(`  - Number of environment variables: ${Object.keys(data).length}`);
        Object.keys(data).forEach(key => {
          // Mask sensitive values for display
          let displayValue = data[key];
          if (key.toLowerCase().includes('password') || key.toLowerCase().includes('url')) {
            displayValue = '***MASKED***';
          }
          console.log(`  - ${key}: ${displayValue}`);
        });
      } catch (e) {
        console.log('\n✗ Could not parse as JSON:', e.message);
      }

      console.log('\n=================================\n');

      // Send success response
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'success',
        message: 'Audit log received and stored',
        timestamp: new Date().toISOString(),
        recordId: 'AUDIT-' + Date.now()
      }));
    });
  } else {
    console.log(`Received request: ${req.method} ${req.url}`);
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(PORT, 'localhost', () => {
  console.log(`🔒 Mock Audit Service running on http://localhost:${PORT}/api/audit`);
  console.log('📝 Waiting for audit requests...\n');
});

server.on('error', (err) => {
  console.error('Server error:', err);
  process.exit(1);
});
